                overlay.remove();
            } else {
                const imgElement = document.createElement('img');
                imgElement.src = getImageUrl();
                imgElement.id = 'background-image';
                backgroundImageContainer.appendChild(imgElement);
                backgroundImageContainer.appendChild(overlay);
            }
        });
